  const s1 = await connecta.search({ connector: "edge-dns", query: "list zones account", safety: "readOnly", includeSchemas: "compact" });
  const s2 = await connecta.search({ connector: "edge-dns", query: "list DNS records", safety: "readOnly", includeSchemas: "compact" });
