async () => {
  const records = await controlled.records({count: 180});
  const items = Array.isArray(records) ? records : (records.records || records.items || records.data);
  if (!Array.isArray(items)) throw new Error("Unexpected records shape: " + JSON.stringify(records).slice(0,300));
  const out = {};
  for (const row of items) {
    const g = row.group;
    if (!out[g]) out[g] = {record_count: 0, score_sum: 0};
    out[g].record_count++;
    out[g].score_sum += row.score;
  }
  return out;
}

